package com.rubiumminer;

final class AmountFormat
{
	private AmountFormat()
	{
	}

	/**
	 * Short amounts for the session box, rounded down: 1503 -> "1503", 25_560 -> "25.5k",
	 * 125_900 -> "125k", 2_340_000 -> "2.3m", 140_000_000 -> "140m".
	 */
	static String compact(long n)
	{
		if (n < 0)
		{
			return "-" + compact(-n);
		}
		if (n < 10_000)
		{
			return Long.toString(n);
		}
		if (n < 100_000)
		{
			return tenths(n / 100) + "k";
		}
		if (n < 1_000_000)
		{
			return n / 1000 + "k";
		}
		if (n < 100_000_000)
		{
			return tenths(n / 100_000) + "m";
		}
		return n / 1_000_000 + "m";
	}

	/**
	 * Session totals, rounded down to one decimal from 1,000 up: 600 -> "600", 2952 -> "2.9k",
	 * 500_380 -> "500.3k", 1_100_000 -> "1.1m".
	 */
	static String total(long n)
	{
		if (n < 0)
		{
			return "-" + total(-n);
		}
		if (n < 1000)
		{
			return Long.toString(n);
		}
		if (n < 1_000_000)
		{
			return tenths(n / 100) + "k";
		}
		return tenths(n / 100_000) + "m";
	}

	/** 255 -> "25.5", 250 -> "25" */
	private static String tenths(long tenths)
	{
		return tenths % 10 == 0 ? Long.toString(tenths / 10) : tenths / 10 + "." + tenths % 10;
	}
}

package com.rubiumminer;

import javax.annotation.Nullable;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * Estimates when the active Rubium deposit will deplete.
 *
 * <p>Only one of the two deposits is active at a time. Once someone starts mining it,
 * it lasts 4 to 5 minutes. The client can't see when another player started, only
 * when the deposit became active and when you started, so the estimate is a range:
 * the true start is somewhere between those two moments.
 */
class DepositTimer
{
	@Value
	static class Estimate
	{
		/** Earliest the deposit can deplete, in ms from now (never negative). */
		long minRemainingMs;
		/** Latest the deposit should deplete, in ms from now (never negative). */
		long maxRemainingMs;
		/** How long you have been mining it, in ms. */
		long minedForMs;
	}

	@Nullable
	private WorldPoint active;
	/** When the active deposit appeared, or -1 if it was already active when the scene loaded. */
	private long activeSince = -1;
	/** When you first mined the active deposit, or -1 if you haven't. */
	private long minedSince = -1;

	void onActive(WorldPoint location, long now, boolean observed)
	{
		active = location;
		activeSince = observed ? now : -1;
		minedSince = -1;
	}

	/** You mined (or clicked Mine on) the deposit at {@code location}. */
	void onMined(WorldPoint location, long now)
	{
		if (location.equals(active) && minedSince < 0)
		{
			minedSince = now;
		}
	}

	/** You got a geode, so you're mining whichever deposit is active. */
	void onGeode(long now)
	{
		if (active != null && minedSince < 0)
		{
			minedSince = now;
		}
	}

	/** @return true if the depleted deposit was the active one */
	boolean onDepleted(WorldPoint location)
	{
		if (location.equals(active))
		{
			active = null;
			activeSince = -1;
			minedSince = -1;
			return true;
		}
		return false;
	}

	void clear()
	{
		active = null;
		activeSince = -1;
		minedSince = -1;
	}

	@Nullable
	WorldPoint getActive()
	{
		return active;
	}

	/** @return the depletion window, or null until you have started mining the active deposit */
	@Nullable
	Estimate estimate(long now)
	{
		if (active == null || minedSince < 0)
		{
			return null;
		}
		// Earliest possible start is when it appeared; latest is when you started.
		long earliestStart = activeSince >= 0 ? Math.min(activeSince, minedSince) : minedSince;
		long min = Math.max(0, earliestStart + RubiumData.DEPOSIT_MIN_MS - now);
		long max = Math.max(0, minedSince + RubiumData.DEPOSIT_MAX_MS - now);
		return new Estimate(min, max, now - minedSince);
	}
}

package com.rubiumminer;

final class DurationFormat
{
	private DurationFormat()
	{
	}

	/** 95_000 -> "1:35" */
	static String clock(long ms)
	{
		long seconds = Math.max(0, ms) / 1000;
		return String.format("%d:%02d", seconds / 60, seconds % 60);
	}

	/** Whole seconds, rounded up so it reads "1s" until the very end: 34_100 -> "35s" */
	static String seconds(long ms)
	{
		return (Math.max(0, ms) + 999) / 1000 + "s";
	}

	/** "1:35" when both ends match to the second, else "0:35-1:35" */
	static String range(long minMs, long maxMs)
	{
		String min = clock(minMs);
		String max = clock(maxMs);
		return min.equals(max) ? max : min + "-" + max;
	}
}

package com.rubiumminer;

/**
 * Splinters, geodes and Mining XP gained since the session started. A session starts
 * on the first gain and ends after {@code timeoutMs} with no gains.
 *
 * <p>Hourly rates use active time, not wall-clock time: the time between one interaction
 * (a gain, or clicking Mine) and the next, skipping any gap longer than {@link #IDLE_GAP_MS}.
 * Banking, AFK breaks and walking off don't drag the rates down.
 */
class MiningSession
{
	/** A pause longer than this between interactions counts as idle and is left out of the rates. */
	static final long IDLE_GAP_MS = 60_000;
	/** Rates show 0 until this much active time has passed, so early numbers don't spike. */
	static final long MIN_ACTIVE_MS = 60_000;

	private long startedAt = -1;
	private long lastGainAt = -1;
	private long lastActivityAt = -1;
	private long activeMs;
	private int splinters;
	private int geodes;
	private int xp;

	void addSplinters(int n, long now)
	{
		gain(now);
		splinters += n;
	}

	void addGeodes(int n, long now)
	{
		gain(now);
		geodes += n;
	}

	void addXp(int n, long now)
	{
		gain(now);
		xp += n;
	}

	/** You clicked Mine. Counts toward active time, but doesn't start a session on its own. */
	void interact(long now)
	{
		if (isActive())
		{
			activity(now);
		}
		else
		{
			// The walk and first swings before the first gain still count once it arrives
			lastActivityAt = now;
		}
	}

	private void gain(long now)
	{
		if (startedAt < 0)
		{
			startedAt = now;
		}
		lastGainAt = now;
		activity(now);
	}

	private void activity(long now)
	{
		if (lastActivityAt >= 0)
		{
			long gap = now - lastActivityAt;
			if (gap > 0 && gap <= IDLE_GAP_MS)
			{
				activeMs += gap;
			}
		}
		lastActivityAt = Math.max(lastActivityAt, now);
	}

	boolean isActive()
	{
		return startedAt >= 0;
	}

	/** End the session if nothing was gained for {@code timeoutMs}. */
	void expire(long now, long timeoutMs)
	{
		if (isActive() && now - lastGainAt > timeoutMs)
		{
			reset();
		}
	}

	void reset()
	{
		startedAt = -1;
		lastGainAt = -1;
		lastActivityAt = -1;
		activeMs = 0;
		splinters = 0;
		geodes = 0;
		xp = 0;
	}

	int getSplinters()
	{
		return splinters;
	}

	int getGeodes()
	{
		return geodes;
	}

	int getXp()
	{
		return xp;
	}

	long getActiveMs()
	{
		return activeMs;
	}

	/** Per-hour rate for {@code amount} over active time; 0 until there's a minute of it. */
	long perHour(long amount)
	{
		if (activeMs < MIN_ACTIVE_MS)
		{
			return 0;
		}
		return amount * 3_600_000L / activeMs;
	}
}

package com.rubiumminer;

import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * Current state of every Rubium rock and deposit in the loaded scene, keyed by tile.
 */
class RockTracker
{
	@Value
	static class Rock
	{
		WorldPoint location;
		boolean deposit;
		boolean active;
		/** When the state last changed, or -1 if it was already like this when the scene loaded. */
		long changedAt;
	}

	private final Map<WorldPoint, Rock> rocks = new HashMap<>();
	/** Splinters you took from each rock since it last changed state. */
	private final Map<WorldPoint, Integer> yourSplinters = new HashMap<>();
	/** When each depleted rock respawns, from the game's own respawn timer. */
	private final Map<WorldPoint, Long> respawnAt = new HashMap<>();

	/**
	 * Record an object spawn. {@code observed} is false for spawns caused by a scene load,
	 * where we only learn the current state and not when it changed.
	 *
	 * @return the previous state of that tile, or null if it was unknown
	 */
	@Nullable
	Rock update(int objectId, WorldPoint location, long now, boolean observed)
	{
		boolean active = RubiumData.isActive(objectId);
		Rock previous = rocks.get(location);
		boolean changed = previous == null || previous.isActive() != active;
		// A repeat spawn in the same state keeps its history (and its "fresh" status)
		long changedAt = changed ? (observed ? now : -1) : previous.getChangedAt();
		rocks.put(location, new Rock(location, !RubiumData.isRock(objectId), active, changedAt));
		if (changed)
		{
			yourSplinters.remove(location);
		}
		if (active)
		{
			// Only on respawn: the timer can arrive just before the depleted rock spawns
			respawnAt.remove(location);
		}
		return previous;
	}

	void clear()
	{
		rocks.clear();
		yourSplinters.clear();
		respawnAt.clear();
	}

	/** The game started a respawn timer on the depleted rock at {@code location}. */
	void setRespawn(WorldPoint location, long at)
	{
		respawnAt.put(location, at);
	}

	/** Milliseconds until a depleted rock respawns (0 once it's due), or -1 if we didn't see its timer start. */
	long respawnRemainingMs(WorldPoint location, long now)
	{
		Long at = respawnAt.get(location);
		Rock rock = rocks.get(location);
		if (at == null || rock == null || rock.isActive())
		{
			return -1;
		}
		return Math.max(0, at - now);
	}

	/** You got {@code n} splinters from the rock at {@code location}. */
	void addYourSplinters(WorldPoint location, int n)
	{
		yourSplinters.merge(location, n, Integer::sum);
	}

	int yourSplinters(WorldPoint location)
	{
		return yourSplinters.getOrDefault(location, 0);
	}

	/**
	 * Splinters still guaranteed from an active rock, counting only what you took:
	 * every rock gives at least {@link RubiumData#GUARANTEED_SPLINTERS} before it can deplete.
	 *
	 * @return 0 to 2, or -1 if we didn't see the rock respawn and so don't know
	 */
	int guaranteedLeft(WorldPoint location)
	{
		Rock rock = rocks.get(location);
		if (rock == null || rock.isDeposit() || !rock.isActive())
		{
			return 0;
		}
		int taken = yourSplinters(location);
		if (rock.getChangedAt() < 0)
		{
			// Unknown history, but if you alone took two, the guarantee is used up either way
			return taken >= RubiumData.GUARANTEED_SPLINTERS ? 0 : -1;
		}
		return Math.max(0, RubiumData.GUARANTEED_SPLINTERS - taken);
	}

	/** "2 left", "1 left" (guaranteed splinters), then "1 in 6" (depletion chance per splinter), or null if unknown. */
	@Nullable
	String oddsLabel(WorldPoint location)
	{
		int left = guaranteedLeft(location);
		if (left < 0)
		{
			return null;
		}
		return left > 0 ? left + " left" : "1 in " + RubiumData.DEPLETE_ONE_IN;
	}

	/** Active rock we watched respawn that you haven't mined yet. Other players may have. */
	boolean isFresh(Rock rock)
	{
		return !rock.isDeposit() && rock.isActive() && rock.getChangedAt() >= 0 && yourSplinters(rock.getLocation()) == 0;
	}

	boolean isEmpty()
	{
		return rocks.isEmpty();
	}

	@Nullable
	Rock get(WorldPoint location)
	{
		return rocks.get(location);
	}

	Collection<Rock> all()
	{
		return Collections.unmodifiableCollection(rocks.values());
	}

	/** Closest active rubium rock (not deposit) to {@code from}, or null if none. */
	@Nullable
	Rock nearestActiveRock(WorldPoint from)
	{
		Rock best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (Rock rock : rocks.values())
		{
			if (rock.isDeposit() || !rock.isActive() || rock.getLocation().getPlane() != from.getPlane())
			{
				continue;
			}
			int d = rock.getLocation().distanceTo2D(from);
			if (d < bestDistance)
			{
				bestDistance = d;
				best = rock;
			}
		}
		return best;
	}

	int activeRockCount()
	{
		int n = 0;
		for (Rock rock : rocks.values())
		{
			if (!rock.isDeposit() && rock.isActive())
			{
				n++;
			}
		}
		return n;
	}

	int rockCount()
	{
		int n = 0;
		for (Rock rock : rocks.values())
		{
			if (!rock.isDeposit())
			{
				n++;
			}
		}
		return n;
	}
}

package com.rubiumminer;

import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;

/**
 * Rubium facts from the OSRS Wiki (Rubium rocks, Rubium deposit, Rubium geode pages, October 2026).
 */
final class RubiumData
{
	static final int ROCK = ObjectID.RUBIUMROCK1;
	static final int ROCK_EMPTY = ObjectID.RUBIUMROCK1_EMPTY;
	static final int DEPOSIT = ObjectID.RUBIUMDEPOSIT1;
	static final int DEPOSIT_EMPTY = ObjectID.RUBIUMDEPOSIT1_EMPTY;

	static final int SPLINTERS = ItemID.RUBIUM_SPLINTERS;
	static final int GEODE = ItemID.RUBIUM_GEODE;

	static final int DEPOSIT_LEVEL = 68;

	/**
	 * Every rubium rock gives at least this many splinters (to anyone) before it can deplete.
	 * After that, each splinter has about a 1 in 6 chance to deplete it.
	 */
	static final int GUARANTEED_SPLINTERS = 2;
	static final int DEPLETE_ONE_IN = 6;

	/** A deposit lasts 4 to 5 minutes once someone starts mining it. */
	static final long DEPOSIT_MIN_MS = 4 * 60_000L;
	static final long DEPOSIT_MAX_MS = 5 * 60_000L;

	private RubiumData()
	{
	}

	static boolean isRubiumObject(int id)
	{
		return id == ROCK || id == ROCK_EMPTY || id == DEPOSIT || id == DEPOSIT_EMPTY;
	}

	static boolean isRock(int id)
	{
		return id == ROCK || id == ROCK_EMPTY;
	}

	static boolean isActive(int id)
	{
		return id == ROCK || id == DEPOSIT;
	}

	/** Splinters per successful swing on a rubium rock, before Varrock armour / celestial ring / cape. */
	static int splintersPerRockSwing(int visibleMiningLevel)
	{
		return visibleMiningLevel >= 72 ? 2 : 1;
	}

	/**
	 * Average splinters from cracking one geode at a visible Mining level, or 0 below 68.
	 * Wiki ranges: 68-75: 3-7, 76-83: 4-8, 84-91: 5-9, 92+: 6-10.
	 */
	static int averageSplintersPerGeode(int visibleMiningLevel)
	{
		if (visibleMiningLevel >= 92)
		{
			return 8;
		}
		if (visibleMiningLevel >= 84)
		{
			return 7;
		}
		if (visibleMiningLevel >= 76)
		{
			return 6;
		}
		if (visibleMiningLevel >= DEPOSIT_LEVEL)
		{
			return 5;
		}
		return 0;
	}
}

package com.rubiumminer;

import java.awt.Color;
import lombok.AllArgsConstructor;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
