@Slf4j
@PluginDescriptor(
	name = "Rubium Miner",
	description = "Rubium mining helper: rock and deposit highlights, guaranteed-splinter counts, respawn and deposit timers, rates and alerts",
	tags = {"mining", "rubium", "sailing", "charred", "geode", "splinters", "skilling"},
	// Core Mining draws its own session box beside ours. Whichever of the two starts second turns the other
	// off. At launch core plugins start first, so if both are on, Mining wins: switch this plugin on once
	// from the plugin list and Mining stays off from then on.
	conflicts = "Mining"
)
public class RubiumMinerPlugin extends Plugin
{
	private static final int INVENTORY_SIZE = 28;
	// A Mine click on a deposit can land on any of its tiles; match it to the nearest tracked object
	private static final int CLICK_MATCH_DISTANCE = 2;
	// After a scene load the server corrects the map's default rock and deposit states over the next tick or two
	private static final int SETTLE_TICKS = 3;

	@Inject
	private Client client;

	@Inject
	private RubiumMinerConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private RubiumSceneOverlay sceneOverlay;

	@Inject
	private RubiumSessionOverlay sessionOverlay;

	@Inject
	private Notifier notifier;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Getter
	private final RockTracker rocks = new RockTracker();
	@Getter
	private final DepositTimer depositTimer = new DepositTimer();
	@Getter
	private final MiningSession session = new MiningSession();

	// Client thread only
	private final Map<WorldPoint, GameObject> objects = new HashMap<>();
	@Nullable
	private WorldPoint miningTarget;
	/** Ticks left before spawns count as changes we watched happen, rather than part of a scene load. */
	private int settleTicks;
	private int lastSplinters = -1;
	private int lastGeodes = -1;
	private int lastMiningXp = -1;
	private boolean notifiedFull;

	@Provides
	RubiumMinerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RubiumMinerConfig.class);
	}

	@Override
	protected void startUp()
	{
		for (String key : RubiumMinerConfig.OBSOLETE_KEYS)
		{
			configManager.unsetConfiguration(RubiumMinerConfig.GROUP, key);
		}
		overlayManager.add(sceneOverlay);
		overlayManager.add(sessionOverlay);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				lastMiningXp = client.getSkillExperience(Skill.MINING);
				ItemContainer inv = client.getItemContainer(InventoryID.INV);
				if (inv != null)
				{
					lastSplinters = inv.count(RubiumData.SPLINTERS);
					lastGeodes = inv.count(RubiumData.GEODE);
				}
				scanScene();
			}
		});
	}

	/** Objects already loaded don't fire spawn events, so pick them up when the plugin starts. */
	private void scanScene()
	{
		Scene scene = client.getTopLevelWorldView().getScene();
		Tile[][][] tiles = scene.getTiles();
		int plane = client.getTopLevelWorldView().getPlane();
		long now = System.currentTimeMillis();
		for (Tile[] column : tiles[plane])
		{
			for (Tile tile : column)
			{
				if (tile == null)
				{
					continue;
				}
				for (GameObject object : tile.getGameObjects())
				{
					if (object != null && RubiumData.isRubiumObject(object.getId()))
					{
						WorldPoint location = object.getWorldLocation();
						objects.put(location, object);
						rocks.update(object.getId(), location, now, false);
						if (object.getId() == RubiumData.DEPOSIT)
						{
							depositTimer.onActive(location, now, false);
						}
					}
				}
			}
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(sceneOverlay);
		overlayManager.remove(sessionOverlay);
		objects.clear();
		rocks.clear();
		depositTimer.clear();
		session.reset();
		miningTarget = null;
		lastSplinters = lastGeodes = lastMiningXp = -1;
	}

	/** True while Rubium rocks or deposits are loaded, i.e. you're in or near the mine. */
	boolean inMine()
	{
		return !rocks.isEmpty();
	}

	Map<WorldPoint, GameObject> getObjects()
	{
		return Collections.unmodifiableMap(objects);
	}

	@Nullable
	WorldPoint getMiningTarget()
	{
		return miningTarget;
	}

	int visibleMiningLevel()
	{
		return client.getBoostedSkillLevel(Skill.MINING);
	}

	int geodesInInventory()
	{
		return Math.max(0, lastGeodes);
	}

	// ---- scene ----

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOADING || state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			settleTicks = SETTLE_TICKS;
			objects.clear();
			rocks.clear();
			miningTarget = null;
		}
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// A different world has its own deposit state
			depositTimer.clear();
			lastSplinters = lastGeodes = lastMiningXp = -1;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (settleTicks > 0)
		{
			settleTicks--;
		}
		session.expire(System.currentTimeMillis(), config.sessionTimeout() * 60_000L);
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		GameObject object = event.getGameObject();
		int id = object.getId();
		if (!RubiumData.isRubiumObject(id))
		{
			return;
		}

		long now = System.currentTimeMillis();
		WorldPoint location = object.getWorldLocation();
		boolean observed = settleTicks == 0;
		objects.put(location, object);
		RockTracker.Rock previous = rocks.update(id, location, now, observed);

		boolean deposit = !RubiumData.isRock(id);
		boolean active = RubiumData.isActive(id);

		if (deposit && active && (observed || !location.equals(depositTimer.getActive())))
		{
			depositTimer.onActive(location, now, observed);
		}

		boolean depleted = previous != null && previous.isActive() && !active;
		if (!depleted)
		{
			return;
		}

		// Only alert on depletions we watched happen, not the server correcting a freshly loaded scene
		if (deposit)
		{
			if (depositTimer.onDepleted(location) && observed)
			{
				notifier.notify(config.notifyDepositDepleted(), "Rubium deposit depleted. The other deposit is now active.");
			}
		}
		else if (observed && location.equals(miningTarget))
		{
			miningTarget = null;
			notifier.notify(config.notifyRockDepleted(), "Your rubium rock depleted.");
		}
	}

	/**
	 * The game draws its own respawn timer on a depleted rock with this script. Core Mining reads the
	 * same arguments: [1] the tile, [2] the depleted object, [5] the respawn time in ticks.
	 */
	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != ScriptID.ADD_OVERLAYTIMER_LOC)
		{
			return;
		}
		Object[] args = event.getScriptEvent().getArguments();
		if ((int) args[2] == RubiumData.ROCK_EMPTY)
		{
			int ticks = (int) args[5];
			rocks.setRespawn(WorldPoint.fromCoord((int) args[1]),
				System.currentTimeMillis() + (long) ticks * Constants.GAME_TICK_LENGTH);
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		GameObject object = event.getGameObject();
		if (RubiumData.isRubiumObject(object.getId()))
		{
			// The replacement object (active <-> depleted) spawns on the same tile right after
			objects.remove(object.getWorldLocation(), object);
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		// Read-only: we note which rock you chose, and never change or add menu entries
		if (!"Mine".equals(event.getMenuOption()) || !RubiumData.isRubiumObject(event.getId()))
		{
			return;
		}
		var wv = client.getTopLevelWorldView();
		WorldPoint clicked = WorldPoint.fromScene(wv, event.getParam0(), event.getParam1(), wv.getPlane());
		RockTracker.Rock rock = nearestTracked(clicked);
		if (rock == null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		miningTarget = rock.getLocation();
		session.interact(now);
		if (rock.isDeposit())
		{
			depositTimer.onMined(rock.getLocation(), now);
		}
	}

	@Nullable
	private RockTracker.Rock nearestTracked(WorldPoint point)
	{
		RockTracker.Rock best = null;
		int bestDistance = CLICK_MATCH_DISTANCE + 1;
		for (RockTracker.Rock rock : rocks.all())
		{
			int d = rock.getLocation().distanceTo2D(point);
			if (rock.getLocation().getPlane() == point.getPlane() && d < bestDistance)
			{
				bestDistance = d;
				best = rock;
			}
		}
		return best;
	}

	// ---- gains ----

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}
		ItemContainer inv = event.getItemContainer();
		int splinters = inv.count(RubiumData.SPLINTERS);
		int geodes = inv.count(RubiumData.GEODE);
		long now = System.currentTimeMillis();

		// Only count what you gain in the mine, not withdrawals from a bank
		boolean counting = inMine() && !bankOpen() && lastSplinters >= 0;
		if (counting && splinters > lastSplinters)
		{
			int gained = splinters - lastSplinters;
			session.addSplinters(gained, now);

			// Splinters with no geode used up came from a rock: the one you last clicked Mine on
			RockTracker.Rock target = miningTarget == null ? null : rocks.get(miningTarget);
			if (geodes >= lastGeodes && target != null && !target.isDeposit())
			{
				rocks.addYourSplinters(miningTarget, gained);
			}
		}
		if (counting && geodes > lastGeodes)
		{
			session.addGeodes(geodes - lastGeodes, now);
			depositTimer.onGeode(now);
		}
		lastSplinters = splinters;
		lastGeodes = geodes;

		int used = 0;
		for (Item item : inv.getItems())
		{
			if (item.getId() > 0)
			{
				used++;
			}
		}
		if (used < INVENTORY_SIZE)
		{
			notifiedFull = false;
		}
		else if (inMine() && !notifiedFull)
		{
			notifiedFull = true;
			notifier.notify(config.inventoryFullAlert(), geodes > 0
				? "Inventory full: " + geodes + " geodes to crack open."
				: "Inventory full.");
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.MINING)
		{
			return;
		}
		int xp = event.getXp();
		if (lastMiningXp >= 0 && xp > lastMiningXp && inMine())
		{
			session.addXp(xp - lastMiningXp, System.currentTimeMillis());
		}
		lastMiningXp = xp;
	}

	private boolean bankOpen()
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.ITEMS);
		return bank != null && !bank.isHidden();
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		if ("rubium".equalsIgnoreCase(event.getCommand()) && event.getArguments().length > 0
			&& "reset".equalsIgnoreCase(event.getArguments()[0]))
		{
			session.reset();
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage("Rubium Miner session reset.")
				.build());
		}
	}
}

package com.rubiumminer;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Outlines active rubium rocks (thicker for the nearest one) and the active deposit with its
 * depletion timer, counts down depleted rocks' respawns in seconds, and labels the inactive deposit. Outlines only, no fill, and labels sit on a
 * dark backing so they stay readable over the lava. Drawing only: click zones are untouched.
 */
class RubiumSceneOverlay extends Overlay
{
	private static final Stroke THIN = new BasicStroke(1f);
	private static final Stroke THICK = new BasicStroke(2f);
	private static final Color NO_FILL = new Color(0, 0, 0, 0);
	private static final Color LABEL_BACKING = new Color(0, 0, 0, 150);
	private static final Color NEXT_COLOR = new Color(170, 170, 170);
	/** Shared with the session box, where it colors the hourly rates. */
	static final Color GUARANTEED_COLOR = new Color(120, 255, 160);
	private static final int LABEL_PAD_X = 4;
	private static final int LABEL_PAD_Y = 1;
	private static final int LABEL_ARC = 6;

	private final Client client;
	private final RubiumMinerPlugin plugin;
	private final RubiumMinerConfig config;

	@Inject
	RubiumSceneOverlay(Client client, RubiumMinerPlugin plugin, RubiumMinerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!plugin.inMine())
		{
			return null;
		}

		RubiumMinerConfig.RockHighlight highlight = config.rockHighlight();
		Player player = client.getLocalPlayer();
		RockTracker.Rock nearest = player != null && highlight != RubiumMinerConfig.RockHighlight.OFF
			? plugin.getRocks().nearestActiveRock(player.getWorldLocation())
			: null;
		Map<WorldPoint, GameObject> objects = plugin.getObjects();
		long now = System.currentTimeMillis();

		for (RockTracker.Rock rock : plugin.getRocks().all())
		{
			GameObject object = objects.get(rock.getLocation());
			if (object == null)
			{
				continue;
			}
			if (rock.isDeposit())
			{
				renderDeposit(g, object, rock, now);
				continue;
			}
			if (!rock.isActive())
			{
				long respawn = plugin.getRocks().respawnRemainingMs(rock.getLocation(), now);
				if (config.rockLabels() && respawn >= 0)
				{
					label(g, object, DurationFormat.seconds(respawn), Color.WHITE);
				}
				continue;
			}

			if (rock == nearest)
			{
				outline(g, object, config.rockColor(), THICK);
			}
			else if (highlight == RubiumMinerConfig.RockHighlight.ALL)
			{
				outline(g, object, config.rockColor(), THIN);
			}
			if (config.rockLabels())
			{
				renderRockLabel(g, object, rock);
			}
		}
		return null;
	}

	private void renderRockLabel(Graphics2D g, GameObject object, RockTracker.Rock rock)
	{
		RockTracker rocks = plugin.getRocks();
		if (rock.getLocation().equals(plugin.getMiningTarget()))
		{
			String odds = rocks.oddsLabel(rock.getLocation());
			if (odds != null)
			{
				label(g, object, odds, rocks.guaranteedLeft(rock.getLocation()) > 0 ? GUARANTEED_COLOR : Color.WHITE);
			}
		}
		else if (rocks.isFresh(rock))
		{
			label(g, object, "Fresh", GUARANTEED_COLOR);
		}
	}

	private void renderDeposit(Graphics2D g, GameObject object, RockTracker.Rock rock, long now)
	{
		if (!config.highlightDeposit())
		{
			return;
		}
		if (!rock.isActive())
		{
			label(g, object, "Next deposit", NEXT_COLOR);
			return;
		}

		outline(g, object, config.depositColor(), THICK);
		DepositTimer.Estimate estimate = plugin.getDepositTimer().estimate(now);
		String text = estimate == null
			? "Active"
			: estimate.getMaxRemainingMs() == 0
				? "Depleting any moment"
				: "Depletes in " + DurationFormat.range(estimate.getMinRemainingMs(), estimate.getMaxRemainingMs());
		label(g, object, text, config.depositColor());
	}

	private static void outline(Graphics2D g, GameObject object, Color color, Stroke stroke)
	{
		Shape hull = object.getConvexHull();
		if (hull != null)
		{
			OverlayUtil.renderPolygon(g, hull, color, NO_FILL, stroke);
		}
	}

	private static void label(Graphics2D g, GameObject object, String text, Color color)
	{
		Point at = object.getCanvasTextLocation(g, text, 140);
		if (at == null)
		{
			return;
		}
		FontMetrics metrics = g.getFontMetrics();
		Object antialias = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(LABEL_BACKING);
		g.fillRoundRect(
			at.getX() - LABEL_PAD_X,
			at.getY() - metrics.getAscent() - LABEL_PAD_Y,
			metrics.stringWidth(text) + LABEL_PAD_X * 2,
			metrics.getAscent() + metrics.getDescent() + LABEL_PAD_Y * 2,
			LABEL_ARC, LABEL_ARC);
		if (antialias != null)
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, antialias);
		}
		OverlayUtil.renderTextLocation(g, at, text, color);
	}
}

package com.rubiumminer;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

/**
 * Session box, three lines of white totals with green hourly rates:
 * <pre>
 * Splinters: 129 (1503/hr)
 * Mining XP: 3.9k xp (25.5k/hr)
 * GP: 18.5k gp (125k/hr)
 * </pre>
 * Rates are over active time (see {@link MiningSession}). The box widens to fit its text.
 */
class RubiumSessionOverlay extends OverlayPanel
{
	private final RubiumMinerPlugin plugin;
	private final RubiumMinerConfig config;
	private final ItemManager itemManager;

	@Inject
	RubiumSessionOverlay(RubiumMinerPlugin plugin, RubiumMinerConfig config, ItemManager itemManager)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		MiningSession session = plugin.getSession();
		if (!config.showSessionOverlay() || !plugin.inMine() || !session.isActive())
		{
			return null;
		}

		List<String> lines = new ArrayList<>();
		lines.add(line("Splinters", session.getSplinters(), "", session));
		lines.add(line("Mining XP", session.getXp(), " xp", session));
		long price = itemManager.getItemPrice(RubiumData.SPLINTERS);
		if (price > 0)
		{
			lines.add(line("GP", session.getSplinters() * price, " gp", session));
		}

		fitWidth(g, lines);
		for (String text : lines)
		{
			panelComponent.getChildren().add(LineComponent.builder().left(text).build());
		}
		return super.render(g);
	}

	/**
	 * "Mining XP: 6.1k xp (24.6k/hr)", with the rate left off during the first minute of active time.
	 * The rate goes last because overlay text understands an opening color tag but prints a closing one
	 * literally, so the green has to run to the end of the line.
	 */
	private static String line(String label, long total, String unit, MiningSession session)
	{
		long perHour = session.perHour(total);
		String text = label + ": " + AmountFormat.total(total) + unit;
		return perHour > 0
			? text + " " + ColorUtil.prependColorTag("(" + AmountFormat.compact(perHour) + "/hr)", RubiumSceneOverlay.GUARANTEED_COLOR)
			: text;
	}

	/** Widen the box so no line wraps or spills past its edge, including when you've resized it narrower. */
	private void fitWidth(Graphics2D g, List<String> lines)
	{
		FontMetrics metrics = g.getFontMetrics();
		int widest = 0;
		for (String text : lines)
		{
			widest = Math.max(widest, metrics.stringWidth(Text.removeTags(text)));
		}
		int needed = Math.max(ComponentConstants.STANDARD_WIDTH, widest + ComponentConstants.STANDARD_BORDER * 2 + 2);

		Dimension yours = getPreferredSize();
		if (yours == null)
		{
			panelComponent.setPreferredSize(new Dimension(needed, 0));
		}
		else if (yours.width < needed)
		{
			setPreferredSize(new Dimension(needed, yours.height));
		}
	}
}

package com.rubiumminer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.mining.MiningPlugin;
import org.junit.Test;

public class RubiumLogicTest
{
	private static final WorldPoint DEPOSIT_A = new WorldPoint(2679, 8852, 0);
	private static final WorldPoint DEPOSIT_B = new WorldPoint(2685, 8847, 0);

	@Test
	public void yieldsFollowTheWikiTables()
	{
		assertEquals(1, RubiumData.splintersPerRockSwing(48));
		assertEquals(1, RubiumData.splintersPerRockSwing(71));
		assertEquals(2, RubiumData.splintersPerRockSwing(72));

		assertEquals(0, RubiumData.averageSplintersPerGeode(67));
		assertEquals(5, RubiumData.averageSplintersPerGeode(68));
		assertEquals(6, RubiumData.averageSplintersPerGeode(76));
		assertEquals(7, RubiumData.averageSplintersPerGeode(84));
		assertEquals(8, RubiumData.averageSplintersPerGeode(92));
		assertEquals(8, RubiumData.averageSplintersPerGeode(99));
	}

	@Test
	public void idsAreClassified()
	{
		assertTrue(RubiumData.isRubiumObject(58919));
		assertTrue(RubiumData.isRubiumObject(58922));
		assertFalse(RubiumData.isRubiumObject(58918));
		assertTrue(RubiumData.isRock(58920));
		assertFalse(RubiumData.isRock(58921));
		assertTrue(RubiumData.isActive(RubiumData.DEPOSIT));
		assertFalse(RubiumData.isActive(RubiumData.ROCK_EMPTY));
	}

	@Test
	public void trackerFindsNearestActiveRockAndReportsDepletion()
	{
		RockTracker t = new RockTracker();
		WorldPoint near = new WorldPoint(2680, 8836, 0);
		WorldPoint far = new WorldPoint(2687, 8849, 0);
		t.update(RubiumData.ROCK, near, 0, false);
		t.update(RubiumData.ROCK, far, 0, false);
		t.update(RubiumData.DEPOSIT, DEPOSIT_A, 0, false);

		WorldPoint me = new WorldPoint(2681, 8837, 0);
		assertEquals(near, t.nearestActiveRock(me).getLocation());
		assertEquals(2, t.activeRockCount());
		assertEquals(2, t.rockCount());

		RockTracker.Rock previous = t.update(RubiumData.ROCK_EMPTY, near, 1000, true);
		assertTrue("previous state is returned so the plugin can spot depletion", previous.isActive());
		assertEquals(far, t.nearestActiveRock(me).getLocation());
		assertEquals(1000, t.get(near).getChangedAt());

		t.update(RubiumData.ROCK_EMPTY, far, 2000, true);
		assertNull("deposits are never the nearest rock", t.nearestActiveRock(me));
	}

	@Test
	public void guaranteedSplintersCountDownFromAWatchedRespawn()
	{
		RockTracker t = new RockTracker();
		WorldPoint rock = new WorldPoint(2682, 8839, 0);
		t.update(RubiumData.ROCK_EMPTY, rock, 0, true);
		assertEquals("nothing is guaranteed from a depleted rock", 0, t.guaranteedLeft(rock));

		t.update(RubiumData.ROCK, rock, 5_000, true);
		RockTracker.Rock respawned = t.get(rock);
		assertTrue(t.isFresh(respawned));
		assertEquals(2, t.guaranteedLeft(rock));
		assertEquals("2 left", t.oddsLabel(rock));

		t.addYourSplinters(rock, 1);
		assertFalse(t.isFresh(t.get(rock)));
		assertEquals("1 left", t.oddsLabel(rock));

		// At level 72+ one swing gives two splinters
		t.addYourSplinters(rock, 2);
		assertEquals(0, t.guaranteedLeft(rock));
		assertEquals("1 in 6", t.oddsLabel(rock));

		// Depleting and respawning starts over
		t.update(RubiumData.ROCK_EMPTY, rock, 9_000, true);
		t.update(RubiumData.ROCK, rock, 20_000, true);
		assertEquals(0, t.yourSplinters(rock));
		assertEquals("2 left", t.oddsLabel(rock));
	}

